func NewTracesGatewayErrorResponseBody(res *goa.ServiceError) *TracesGatewayErrorResponseBody {
	body := &TracesGatewayErrorResponseBody{
		Name:      res.Name,
		ID:        res.ID,
		Message:   res.Message,
		Temporary: res.Temporary,
		Timeout:   res.Timeout,
		Fault:     res.Fault,
	}
	return body
}

// NewLogsPayload builds a otel service logs endpoint payload.
func NewLogsPayload(apikeyToken *string, projectSlugInput *string, contentEncoding *string) *otel.LogsPayload {
	v := &otel.LogsPayload{}
	v.ApikeyToken = apikeyToken
	v.ProjectSlugInput = projectSlugInput
	v.ContentEncoding = contentEncoding

	return v
}

// NewTracesPayload builds a otel service traces endpoint payload.
func NewTracesPayload(apikeyToken *string, projectSlugInput *string, contentEncoding *string) *otel.TracesPayload {
	v := &otel.TracesPayload{}
	v.ApikeyToken = apikeyToken
	v.ProjectSlugInput = projectSlugInput
	v.ContentEncoding = contentEncoding

	return v
}
